DROP TABLE IF EXISTS `rule_content_security`;
CREATE TABLE `rule_content_security` (
  `id` varchar(64) COLLATE utf8mb4_bin NOT NULL COMMENT '规则 ID（唯一，如 instr-ignore-previous）',
  `category` varchar(32) COLLATE utf8mb4_bin NOT NULL COMMENT '规则分类（instruction_override/role_switch/system_prompt_leak/data_exfiltration/tool_abuse/harmful_content）',
  `severity` varchar(16) COLLATE utf8mb4_bin NOT NULL COMMENT 'INFO | LOW | MEDIUM | HIGH | CRITICAL',
  `action` varchar(16) COLLATE utf8mb4_bin NOT NULL COMMENT 'ALLOW | REVIEW | BLOCK',
  `description` varchar(512) COLLATE utf8mb4_bin NOT NULL COMMENT '规则描述',
  `pattern` text COLLATE utf8mb4_bin NOT NULL COMMENT '命中正则（加载时大小写不敏感预编译）',
  `allowlisted` tinyint NOT NULL DEFAULT '0' COMMENT 'allowlist 标记（1=已加入，命中后不计入风险）',
  `ord` int NOT NULL COMMENT '展示/扫描顺序（原文件声明顺序，新增规则追加尾部）',
  `updated_at` datetime NOT NULL COMMENT '行级写入时间（API 不输出）',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin COMMENT='内容安全规则（每条一行）';
INSERT INTO `rule_content_security` VALUES ('cn-data-exfil','data_exfiltration','HIGH','REVIEW','要求打包发送所有文件（中文）','(?:打包|压缩|发送|上传)\\s*(?:所有|全部)?\\s*(?:文件|数据|资料)',0,25,'2026-10-10 16:10:04'),('cn-delete-data','tool_abuse','CRITICAL','BLOCK','要求删除数据或文件（中文）','(?:删除|清空|清除|移除)\\s*(?:所有|全部)?\\s*(?:数据|文件|资料|记录)',0,26,'2026-10-10 16:10:04'),('cn-guardrail-bypass','role_switch','HIGH','REVIEW','绕过安全机制（中文）','(?:绕过|无视|关闭)\\s*(?:安全|限制|审核)\\s*(?:机制|系统)?',0,23,'2026-10-10 16:10:04'),('cn-harm-drug','harmful_content','CRITICAL','BLOCK','要求生成毒品或违禁品配方（中文）','(?:制作|制造|生成|配方)\\s*(?:毒品|违禁品|毒药|毒物|麻醉品)',0,27,'2026-10-10 16:10:04'),('cn-harm-suicide','harmful_content','HIGH','BLOCK','教唆自杀或自残（中文）','(?:如何|怎么|怎样|教我|方法)\\s*(?:自杀|自残|轻生|自伤|结束生命)',0,28,'2026-10-10 16:10:04'),('cn-ignore-everything','instruction_override','HIGH','REVIEW','无视所有指令或规则（中文）','无视\\s*(?:所有|全部)?\\s*(?:指令|规则|限制|要求|内容)',0,19,'2026-10-10 16:10:04'),('cn-ignore-previous','instruction_override','HIGH','REVIEW','要求模型忽略之前的指令（中文）','忽略\\s*(?:之前|以上|前面|上面)\\s*(?:的)?\\s*(?:所有|全部)?\\s*(?:指令|指示|提示|要求|内容)',0,18,'2026-10-10 16:10:04'),('cn-jailbreak','role_switch','HIGH','REVIEW','越狱/解除限制表达（中文）','(?:越狱|解除限制|破解限制)',0,22,'2026-10-10 16:10:04'),('cn-leak-prompt','system_prompt_leak','HIGH','REVIEW','要求模型透露系统提示词（中文）','(?:输出|复述|展示|告诉我)\\s*(?:你的|系统|所有)?\\s*(?:提示词|系统提示|指令)',0,21,'2026-10-10 16:10:04'),('cn-tool-abuse','tool_abuse','CRITICAL','BLOCK','要求执行任意命令（中文）','(?:执行|运行)\\s*(?:任意|恶意|危险|不受限制的)\\s*命令',0,24,'2026-10-10 16:10:04'),('cn-you-are-now','role_switch','HIGH','REVIEW','将模型切换为其他角色（中文）','你现在(?:是|变成)(?!怎么)',1,20,'2026-10-10 16:10:04'),('exfil-send-external','data_exfiltration','HIGH','REVIEW','Tries to send or exfiltrate data to an external destination','(?:exfiltrate|steal|send|upload|post|transmit)\\s+(?:(?:all|any|the|my|our)\\s+)*(?:data|files?|documents?|messages?|secrets?|credentials?)\\s+(?:to|via|through)',0,11,'2026-10-10 16:10:04'),('exfil-url','data_exfiltration','CRITICAL','BLOCK','Tries to push content to a remote URL','(?:send|upload|post|exfiltrate)\\s+(?:(?:all|any|the|my|our)\\s+)*(?:data|files?|documents?|messages?|everything|it|them)\\s+to\\s+https?://',0,12,'2026-10-10 16:10:04'),('harm-explosive','harmful_content','CRITICAL','BLOCK','Requests instructions for explosives','(?:how\\s+to\\s+)?(?:make|build|create)\\s+(?:a|an)?\\s*(?:bomb|explosive|incendiary\\s+device)(?!\\s*(?:shelter|threat|squad|disposal|scare|attack|scenario))',0,15,'2026-10-10 16:10:04'),('harm-malware','harmful_content','CRITICAL','BLOCK','Requests malware or ransomware development','(?:write|create|develop)\\s+(?:a|an)?\\s*(?:malware|ransomware|virus|keylogger|trojan)',0,17,'2026-10-10 16:10:04'),('harm-weapon','harmful_content','CRITICAL','BLOCK','Requests instructions for weapons','instructions?\\s+for\\s+(?:making|building)\\s+(?:a|an)?\\s*(?:weapon|firearm|gun)',0,16,'2026-10-10 16:10:04'),('huangse','harmful_content','HIGH','BLOCK','找小姐黄色信息','(?:如何|怎么|怎样|教我|方法)\\s*(?:小姐|嫖娼|鸡)',0,29,'2026-10-10 16:10:04'),('instr-disregard','instruction_override','HIGH','REVIEW','Tries to disregard earlier instructions','disregard\\s+(?:all\\s+|any\\s+)?(?:previous|prior|above|earlier)\\s+(?:instructions?|prompts?|messages?|content)',0,2,'2026-10-10 16:10:04'),('instr-forget','instruction_override','HIGH','REVIEW','Asks the model to forget prior instructions','forget\\s+(?:all\\s+|everything|anything)?\\s*(?:you\\s+(?:were|have)\\s+(?:told|given|instructed)|prior\\s+instructions?|previous\\s+instructions?)',0,3,'2026-10-10 16:10:04'),('instr-ignore-previous','instruction_override','HIGH','REVIEW','Tries to discard or override earlier instructions','ignore\\s+(?:all\\s+|any\\s+)?(?:previous|prior|above|earlier)\\s+(?:instructions?|prompts?|messages?|content)',0,1,'2026-10-10 16:10:04'),('instr-start-fresh','instruction_override','MEDIUM','REVIEW','Asks to restart the conversation and drop prior context','(?:start|begin)\\s+(?:a\\s+)?(?:new|fresh)\\s+(?:conversation|session|chat)\\s+(?:from\\s+scratch|without\\s+context)?',0,4,'2026-10-10 16:10:04'),('jinzhijiaopai','harmful_content','HIGH','BLOCK','禁止教派内容','(?i)(法沦功|李宏志|邪教)',0,30,'2026-10-10 16:10:04'),('leak-repeat-instructions','system_prompt_leak','HIGH','REVIEW','Asks the model to repeat its instructions verbatim','(?:repeat|copy|quote)\\s+(?:your|the)\\s+(?:full\\s+)?instructions?',0,10,'2026-10-10 16:10:04'),('leak-system-prompt','system_prompt_leak','HIGH','REVIEW','Asks the model to reveal its system prompt or instructions','(?:reveal|show|print|output|display|dump)\\s+(?:your|the|its)\\s+(?:full\\s+)?(?:system\\s+)?(?:prompt|instructions?)',0,9,'2026-10-10 16:10:04'),('role-act-as','role_switch','LOW','REVIEW','Persona framing (\"act as ...\"); benign in most professional prompts','(?:act|behave)\\s+as\\s+(?:if\\s+you\\s+are\\s+|you\\s+are\\s+)?(?:a|an)?\\s*\\w{3,}',0,6,'2026-10-10 16:10:04'),('role-dan-mode','role_switch','HIGH','BLOCK','DAN (Do Anything Now) style jailbreak','\\bDAN\\s+mode\\b|\\bdo\\s+anything\\s+now\\b|\\bdeveloper\\s+mode\\s+on\\b|\\b(?:jailbreak|jail\\s*break)\\s+(?:the|this|my|your)?\\s*(?:model|assistant|ai|bot|system)\\b',0,8,'2026-10-10 16:10:04'),('role-ignore-guardrails','role_switch','CRITICAL','BLOCK','Tries to bypass or disable safety guardrails','(?:ignore|bypass|override|disable|remove|forget)\\s+(?:all\\s+|your\\s+)?(?:safety|guardrails?|restrictions?|constraints?|policies?|filters?)',0,7,'2026-10-10 16:10:04'),('role-you-are-now','role_switch','HIGH','REVIEW','Tries to switch the model into a different persona','you\\s+are\\s+now\\s+',0,5,'2026-10-10 16:10:04'),('tool-destructive','tool_abuse','CRITICAL','BLOCK','Destructive file operations','\\brm\\s+-rf\\b|\\bdelete\\s+all\\s+files\\b|\\bwipe\\s+(?:the\\s+)?(?:disk|drive)\\b',0,14,'2026-10-10 16:10:04'),('tool-shell-commands','tool_abuse','CRITICAL','BLOCK','Tries to get arbitrary shell commands executed','(?:run|execute)\\s+(?:arbitrary|shell|system|terminal|command\\s+line)?\\s*commands?',0,13,'2026-10-10 16:10:04');

